insert into public.prophets (id,name_ar,name_en,slug,bio_ar,bio_en,birth_place_ar,death_place_ar,order_num,published,metadata) values ('9036b881-9e97-4ef5-8946-800e9d08ab66','آدم عليه السلام','Adam','adam','خلق الله آدم من تراب وأسكنه الجنة وعلّمه الأسماء كلها. وبعد نزوله إلى الأرض تاب إلى ربه، فكان أول البشر وأول الأنبياء، وبدأت معه رحلة التوحيد وعمارة الأرض.','A prophet mentioned in the Quran and Islamic tradition.','الجنة والأرض','الجزيرة العربية',1,true,'{"content_source":"Original editorial summary based on Quran and authenticated Islamic tradition","editor":"Zikr"}') on conflict (slug) do update set name_ar=excluded.name_ar,name_en=excluded.name_en,bio_ar=excluded.bio_ar,bio_en=excluded.bio_en,birth_place_ar=excluded.birth_place_ar,death_place_ar=excluded.death_place_ar,order_num=excluded.order_num,published=true,metadata=excluded.metadata;
insert into public.prophet_sections (id,prophet_id,title_ar,title_en,content_ar,content_en,section_type,order_num) values ('45e01867-cb03-5c48-90e6-e5a3e3362121','9036b881-9e97-4ef5-8946-800e9d08ab66','لمحة القصة','Story overview','تبدأ القصة من أصلها كما ورد في القرآن والسنة الصحيحة، مع التركيز على التوحيد والصبر والعمل الصالح. خلق الله آدم من تراب وأسكنه الجنة وعلّمه الأسماء كلها. وبعد نزوله إلى الأرض تاب إلى ربه، فكان أول البشر وأول الأنبياء، وبدأت معه رحلة التوحيد وعمارة الأرض.','This section is an original editorial summary for educational use.','biography',1) on conflict (id) do update set prophet_id=excluded.prophet_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,section_type=excluded.section_type,order_num=excluded.order_num;
insert into public.prophet_sections (id,prophet_id,title_ar,title_en,content_ar,content_en,section_type,order_num) values ('3fb999b9-1a00-5ab3-87ce-fcccb9d7ad2b','9036b881-9e97-4ef5-8946-800e9d08ab66','الدروس والعبر','Lessons and reflections','تعلّمنا سيرة هذا النبي أن الإيمان يظهر في المواقف، وأن الصبر والصدق والرجوع إلى الله طريق النجاة. خلق الله آدم من تراب وأسكنه الجنة وعلّمه الأسماء كلها. وبعد نزوله إلى الأرض تاب إلى ربه، فكان أول البشر وأول الأنبياء، وبدأت معه رحلة التوحيد وعمارة الأرض.','This section is an original editorial summary for educational use.','teachings',2) on conflict (id) do update set prophet_id=excluded.prophet_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,section_type=excluded.section_type,order_num=excluded.order_num;
insert into public.prophet_sections (id,prophet_id,title_ar,title_en,content_ar,content_en,section_type,order_num) values ('d5173c31-4d97-5f10-8350-e64d0d09db8a','9036b881-9e97-4ef5-8946-800e9d08ab66','آيات مرتبطة','Quran connections','تظهر معاني قصة آدم عليه السلام في مواضع متعددة من القرآن الكريم، ويستحسن تدبر سياق الآيات وعدم فصل القصة عن مقصدها في إصلاح القلب والعمل. يمكن للقارئ أن يراجع الآيات التي ذكرت هذا النبي، وأن يتدبر كيف يربط القرآن بين القصة والهداية والسلوك.','This section is an original editorial summary for educational use.','legacy',3) on conflict (id) do update set prophet_id=excluded.prophet_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,section_type=excluded.section_type,order_num=excluded.order_num;
insert into public.prophets (id,name_ar,name_en,slug,bio_ar,bio_en,birth_place_ar,death_place_ar,order_num,published,metadata) values ('e5cad004-e404-582e-87e9-2f74e847fc8b','إدريس عليه السلام','Idris','idris','كان إدريس عليه السلام صديقًا نبيًا، دعا قومه إلى عبادة الله وترك الفساد. اشتهر بالصدق والعلم والعمل، وذكر القرآن أن الله رفعه مكانًا عليًا.','A prophet mentioned in the Quran and Islamic tradition.','بابل ثم مصر','مصر',2,true,'{"content_source":"Original editorial summary based on Quran and authenticated Islamic tradition","editor":"Zikr"}') on conflict (slug) do update set name_ar=excluded.name_ar,name_en=excluded.name_en,bio_ar=excluded.bio_ar,bio_en=excluded.bio_en,birth_place_ar=excluded.birth_place_ar,death_place_ar=excluded.death_place_ar,order_num=excluded.order_num,published=true,metadata=excluded.metadata;
