insert into public.prophets (id,name_ar,name_en,slug,bio_ar,bio_en,birth_place_ar,death_place_ar,order_num,published,metadata) values ('ff4da8d3-9c8f-5c13-99c4-17c443332cdb','هود عليه السلام','Hud','hud','أرسل الله هودًا إلى عاد، وكانوا أصحاب قوة وبناء لكنهم اغتروا بقدرتهم. دعاهم إلى التوحيد والعدل، فلما أصروا على الكبر أرسل الله عليهم ريحًا صرصرًا عاتية وأنجى هودًا ومن آمن.','A prophet mentioned in the Quran and Islamic tradition.','الأحقاف','حضرموت',4,true,'{"content_source":"Original editorial summary based on Quran and authenticated Islamic tradition","editor":"Zikr"}') on conflict (slug) do update set name_ar=excluded.name_ar,name_en=excluded.name_en,bio_ar=excluded.bio_ar,bio_en=excluded.bio_en,birth_place_ar=excluded.birth_place_ar,death_place_ar=excluded.death_place_ar,order_num=excluded.order_num,published=true,metadata=excluded.metadata;
