insert into public.prophets (id,name_ar,name_en,slug,bio_ar,bio_en,birth_place_ar,death_place_ar,order_num,published,metadata) values ('d4b2de49-67af-563c-953d-2762cb9603b1','صالح عليه السلام','Salih','salih','دعا صالح قوم ثمود إلى عبادة الله، وجاءتهم الناقة آية واضحة. اتفق المعتدون على عقرها، فحذّرهم صالح من عذاب قريب، فجاءتهم الصيحة فأصبحوا في ديارهم جاثمين.','A prophet mentioned in the Quran and Islamic tradition.','الحِجر','مدائن صالح',5,true,'{"content_source":"Original editorial summary based on Quran and authenticated Islamic tradition","editor":"Zikr"}') on conflict (slug) do update set name_ar=excluded.name_ar,name_en=excluded.name_en,bio_ar=excluded.bio_ar,bio_en=excluded.bio_en,birth_place_ar=excluded.birth_place_ar,death_place_ar=excluded.death_place_ar,order_num=excluded.order_num,published=true,metadata=excluded.metadata;
