insert into public.prophet_sections (id,prophet_id,title_ar,title_en,content_ar,content_en,section_type,order_num) values ('22c4e455-84e6-566f-82ea-bcde29482ebd','d4b2de49-67af-563c-953d-2762cb9603b1','آيات مرتبطة','Quran connections','تظهر معاني قصة صالح عليه السلام في مواضع متعددة من القرآن الكريم، ويستحسن تدبر سياق الآيات وعدم فصل القصة عن مقصدها في إصلاح القلب والعمل. يمكن للقارئ أن يراجع الآيات التي ذكرت هذا النبي، وأن يتدبر كيف يربط القرآن بين القصة والهداية والسلوك.','This section is an original editorial summary for educational use.','legacy',3) on conflict (id) do update set prophet_id=excluded.prophet_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,section_type=excluded.section_type,order_num=excluded.order_num;
insert into public.prophets (id,name_ar,name_en,slug,bio_ar,bio_en,birth_place_ar,death_place_ar,order_num,published,metadata) values ('422f95ab-7964-4419-9e16-61b62595484c','إبراهيم عليه السلام','Abraham','ibrahim','واجه إبراهيم عليه السلام عبادة الكواكب والأصنام بالحجة، وحطّم الأصنام ليوقظ عقول قومه. أُلقي في النار فنجّاه الله، ثم رفع قواعد الكعبة مع إسماعيل، فصار إمامًا في التوحيد والابتلاء.','A prophet mentioned in the Quran and Islamic tradition.','العراق','مكة والخليل',6,true,'{"content_source":"Original editorial summary based on Quran and authenticated Islamic tradition","editor":"Zikr"}') on conflict (slug) do update set name_ar=excluded.name_ar,name_en=excluded.name_en,bio_ar=excluded.bio_ar,bio_en=excluded.bio_en,birth_place_ar=excluded.birth_place_ar,death_place_ar=excluded.death_place_ar,order_num=excluded.order_num,published=true,metadata=excluded.metadata;
insert into public.prophet_sections (id,prophet_id,title_ar,title_en,content_ar,content_en,section_type,order_num) values ('42b6abe5-c042-5d69-888a-00c64cb18fcb','422f95ab-7964-4419-9e16-61b62595484c','لمحة القصة','Story overview','تبدأ القصة من أصلها كما ورد في القرآن والسنة الصحيحة، مع التركيز على التوحيد والصبر والعمل الصالح. واجه إبراهيم عليه السلام عبادة الكواكب والأصنام بالحجة، وحطّم الأصنام ليوقظ عقول قومه. أُلقي في النار فنجّاه الله، ثم رفع قواعد الكعبة مع إسماعيل، فصار إمامًا في التوحيد والابتلاء.','This section is an original editorial summary for educational use.','biography',1) on conflict (id) do update set prophet_id=excluded.prophet_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,section_type=excluded.section_type,order_num=excluded.order_num;
insert into public.prophet_sections (id,prophet_id,title_ar,title_en,content_ar,content_en,section_type,order_num) values ('02a7df65-ccd7-5268-9b95-abf08ff8118c','422f95ab-7964-4419-9e16-61b62595484c','الدروس والعبر','Lessons and reflections','تعلّمنا سيرة هذا النبي أن الإيمان يظهر في المواقف، وأن الصبر والصدق والرجوع إلى الله طريق النجاة. واجه إبراهيم عليه السلام عبادة الكواكب والأصنام بالحجة، وحطّم الأصنام ليوقظ عقول قومه. أُلقي في النار فنجّاه الله، ثم رفع قواعد الكعبة مع إسماعيل، فصار إمامًا في التوحيد والابتلاء.','This section is an original editorial summary for educational use.','teachings',2) on conflict (id) do update set prophet_id=excluded.prophet_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,section_type=excluded.section_type,order_num=excluded.order_num;
