insert into public.prophets (id,name_ar,name_en,slug,bio_ar,bio_en,birth_place_ar,death_place_ar,order_num,published,metadata) values ('60651ae2-e12a-5be9-9702-2d447ad56c88','لوط عليه السلام','Lot','lut','دعا لوط قومه إلى الطهارة وترك الفواحش، وحذّرهم من عاقبة الظلم. لما أصروا على الجريمة جاءتهم الملائكة وبشرت لوطًا بالنجاة، وأهلكت القرية الظالمة بحجارة من سجيل.','A prophet mentioned in the Quran and Islamic tradition.','العراق','سدوم',7,true,'{"content_source":"Original editorial summary based on Quran and authenticated Islamic tradition","editor":"Zikr"}') on conflict (slug) do update set name_ar=excluded.name_ar,name_en=excluded.name_en,bio_ar=excluded.bio_ar,bio_en=excluded.bio_en,birth_place_ar=excluded.birth_place_ar,death_place_ar=excluded.death_place_ar,order_num=excluded.order_num,published=true,metadata=excluded.metadata;
