insert into public.prophets (id,name_ar,name_en,slug,bio_ar,bio_en,birth_place_ar,death_place_ar,order_num,published,metadata) values ('4c036b16-cf6c-52d8-9232-094ff5f6e7d6','يعقوب عليه السلام','Jacob','yaqub','كان يعقوب إسرائيل الله ونبيًا كريمًا، ربّى أبناءه على التوحيد وحسن الخلق. ابتُلي بفقد يوسف ثم بنيامين، لكنه قال: فصبر جميل، ولم يفقد رجاءه في الله حتى جمعه الله بأبنائه.','A prophet mentioned in the Quran and Islamic tradition.','الخليل','الشام',10,true,'{"content_source":"Original editorial summary based on Quran and authenticated Islamic tradition","editor":"Zikr"}') on conflict (slug) do update set name_ar=excluded.name_ar,name_en=excluded.name_en,bio_ar=excluded.bio_ar,bio_en=excluded.bio_en,birth_place_ar=excluded.birth_place_ar,death_place_ar=excluded.death_place_ar,order_num=excluded.order_num,published=true,metadata=excluded.metadata;
