insert into public.prophet_sections (id,prophet_id,title_ar,title_en,content_ar,content_en,section_type,order_num) values ('3a1af455-0916-59dc-94bb-1a543dde974e','4c036b16-cf6c-52d8-9232-094ff5f6e7d6','آيات مرتبطة','Quran connections','تظهر معاني قصة يعقوب عليه السلام في مواضع متعددة من القرآن الكريم، ويستحسن تدبر سياق الآيات وعدم فصل القصة عن مقصدها في إصلاح القلب والعمل. يمكن للقارئ أن يراجع الآيات التي ذكرت هذا النبي، وأن يتدبر كيف يربط القرآن بين القصة والهداية والسلوك.','This section is an original editorial summary for educational use.','legacy',3) on conflict (id) do update set prophet_id=excluded.prophet_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,section_type=excluded.section_type,order_num=excluded.order_num;
insert into public.prophets (id,name_ar,name_en,slug,bio_ar,bio_en,birth_place_ar,death_place_ar,order_num,published,metadata) values ('ba7abf32-91d7-42a3-b428-28ca6c990403','يوسف عليه السلام','Joseph','yusuf','رأى يوسف رؤيا عظيمة، فحسده إخوته وألقوه في الجب، ثم بيع عبدًا ودخل السجن ظلمًا. ثبّته الله حتى صار أمينًا على خزائن مصر، وعفا عن إخوته حين قدر عليهم، فاجتمع شمل الأسرة.','A prophet mentioned in the Quran and Islamic tradition.','الشام','مصر',11,true,'{"content_source":"Original editorial summary based on Quran and authenticated Islamic tradition","editor":"Zikr"}') on conflict (slug) do update set name_ar=excluded.name_ar,name_en=excluded.name_en,bio_ar=excluded.bio_ar,bio_en=excluded.bio_en,birth_place_ar=excluded.birth_place_ar,death_place_ar=excluded.death_place_ar,order_num=excluded.order_num,published=true,metadata=excluded.metadata;
