insert into public.prophets (id,name_ar,name_en,slug,bio_ar,bio_en,birth_place_ar,death_place_ar,order_num,published,metadata) values ('6f44a03b-234c-440b-bb00-a17ed7f7f83c','أيوب عليه السلام','Job','ayyub','ابتُلي أيوب في صحته وماله وأهله، فثبت على الأدب مع الله ولم يتسخط. دعا ربه دعاءً خاشعًا، فكشف الله ضره ورد عليه أهله ومثلهم معهم، فصار صبره مثلًا خالدًا.','A prophet mentioned in the Quran and Islamic tradition.','الشام','الشام',12,true,'{"content_source":"Original editorial summary based on Quran and authenticated Islamic tradition","editor":"Zikr"}') on conflict (slug) do update set name_ar=excluded.name_ar,name_en=excluded.name_en,bio_ar=excluded.bio_ar,bio_en=excluded.bio_en,birth_place_ar=excluded.birth_place_ar,death_place_ar=excluded.death_place_ar,order_num=excluded.order_num,published=true,metadata=excluded.metadata;
