insert into public.prophets (id,name_ar,name_en,slug,bio_ar,bio_en,birth_place_ar,death_place_ar,order_num,published,metadata) values ('e1c6c8cf-c480-50df-99e5-bb06ce28cc27','هارون عليه السلام','Aaron','harun','كان هارون فصيح اللسان، فاختاره الله وزيرًا لموسى ومعينًا له في الدعوة. واجه مع أخيه فرعون، ثم حافظ على وحدة بني إسرائيل ونصحهم حين عبدوا العجل.','A prophet mentioned in the Quran and Islamic tradition.','مصر','مصر',15,true,'{"content_source":"Original editorial summary based on Quran and authenticated Islamic tradition","editor":"Zikr"}') on conflict (slug) do update set name_ar=excluded.name_ar,name_en=excluded.name_en,bio_ar=excluded.bio_ar,bio_en=excluded.bio_en,birth_place_ar=excluded.birth_place_ar,death_place_ar=excluded.death_place_ar,order_num=excluded.order_num,published=true,metadata=excluded.metadata;
