insert into public.prophet_sections (id,prophet_id,title_ar,title_en,content_ar,content_en,section_type,order_num) values ('894e21c1-c7ce-53c8-8e1a-a8fac45d0b76','e1c6c8cf-c480-50df-99e5-bb06ce28cc27','الدروس والعبر','Lessons and reflections','تعلّمنا سيرة هذا النبي أن الإيمان يظهر في المواقف، وأن الصبر والصدق والرجوع إلى الله طريق النجاة. كان هارون فصيح اللسان، فاختاره الله وزيرًا لموسى ومعينًا له في الدعوة. واجه مع أخيه فرعون، ثم حافظ على وحدة بني إسرائيل ونصحهم حين عبدوا العجل.','This section is an original editorial summary for educational use.','teachings',2) on conflict (id) do update set prophet_id=excluded.prophet_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,section_type=excluded.section_type,order_num=excluded.order_num;
insert into public.prophet_sections (id,prophet_id,title_ar,title_en,content_ar,content_en,section_type,order_num) values ('94302654-ffb0-5312-8120-582e7908d437','e1c6c8cf-c480-50df-99e5-bb06ce28cc27','آيات مرتبطة','Quran connections','تظهر معاني قصة هارون عليه السلام في مواضع متعددة من القرآن الكريم، ويستحسن تدبر سياق الآيات وعدم فصل القصة عن مقصدها في إصلاح القلب والعمل. يمكن للقارئ أن يراجع الآيات التي ذكرت هذا النبي، وأن يتدبر كيف يربط القرآن بين القصة والهداية والسلوك.','This section is an original editorial summary for educational use.','legacy',3) on conflict (id) do update set prophet_id=excluded.prophet_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,section_type=excluded.section_type,order_num=excluded.order_num;
insert into public.prophets (id,name_ar,name_en,slug,bio_ar,bio_en,birth_place_ar,death_place_ar,order_num,published,metadata) values ('8ebb1d27-ec05-5d7a-9646-1d5541970411','ذو الكفل عليه السلام','Dhul-Kifl','dhulkifl','ذكر الله ذا الكفل مع الصابرين والأخيار، فاشتهر بالوفاء بالعهد وكثرة العبادة وضبط النفس. وتعلّم قصته أن المسؤولية تحتاج إلى صبر وصدق لا إلى الكلام وحده.','A prophet mentioned in the Quran and Islamic tradition.','بلاد الشام','بلاد الشام',16,true,'{"content_source":"Original editorial summary based on Quran and authenticated Islamic tradition","editor":"Zikr"}') on conflict (slug) do update set name_ar=excluded.name_ar,name_en=excluded.name_en,bio_ar=excluded.bio_ar,bio_en=excluded.bio_en,birth_place_ar=excluded.birth_place_ar,death_place_ar=excluded.death_place_ar,order_num=excluded.order_num,published=true,metadata=excluded.metadata;
