insert into public.prophets (id,name_ar,name_en,slug,bio_ar,bio_en,birth_place_ar,death_place_ar,order_num,published,metadata) values ('ad17b837-b8e2-5cbb-ad7a-bdacbea9dea7','إلياس عليه السلام','Elijah','ilyas','دعا إلياس قومه إلى ترك عبادة بعل والرجوع إلى الله الواحد. واجه ضغط المجتمع بثبات، وأعلن أن الخالق وحده المستحق للعبادة، فخلّد القرآن ذكره في الصالحين.','A prophet mentioned in the Quran and Islamic tradition.','بعلبك','الشام',20,true,'{"content_source":"Original editorial summary based on Quran and authenticated Islamic tradition","editor":"Zikr"}') on conflict (slug) do update set name_ar=excluded.name_ar,name_en=excluded.name_en,bio_ar=excluded.bio_ar,bio_en=excluded.bio_en,birth_place_ar=excluded.birth_place_ar,death_place_ar=excluded.death_place_ar,order_num=excluded.order_num,published=true,metadata=excluded.metadata;
insert into public.prophet_sections (id,prophet_id,title_ar,title_en,content_ar,content_en,section_type,order_num) values ('694f8043-fbf8-5925-adb2-be0d2863ad3c','ad17b837-b8e2-5cbb-ad7a-bdacbea9dea7','لمحة القصة','Story overview','تبدأ القصة من أصلها كما ورد في القرآن والسنة الصحيحة، مع التركيز على التوحيد والصبر والعمل الصالح. دعا إلياس قومه إلى ترك عبادة بعل والرجوع إلى الله الواحد. واجه ضغط المجتمع بثبات، وأعلن أن الخالق وحده المستحق للعبادة، فخلّد القرآن ذكره في الصالحين.','This section is an original editorial summary for educational use.','biography',1) on conflict (id) do update set prophet_id=excluded.prophet_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,section_type=excluded.section_type,order_num=excluded.order_num;
insert into public.prophet_sections (id,prophet_id,title_ar,title_en,content_ar,content_en,section_type,order_num) values ('7f7322b6-c1bd-57db-94e5-06d523dbaffa','ad17b837-b8e2-5cbb-ad7a-bdacbea9dea7','الدروس والعبر','Lessons and reflections','تعلّمنا سيرة هذا النبي أن الإيمان يظهر في المواقف، وأن الصبر والصدق والرجوع إلى الله طريق النجاة. دعا إلياس قومه إلى ترك عبادة بعل والرجوع إلى الله الواحد. واجه ضغط المجتمع بثبات، وأعلن أن الخالق وحده المستحق للعبادة، فخلّد القرآن ذكره في الصالحين.','This section is an original editorial summary for educational use.','teachings',2) on conflict (id) do update set prophet_id=excluded.prophet_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,section_type=excluded.section_type,order_num=excluded.order_num;
