insert into public.prophets (id,name_ar,name_en,slug,bio_ar,bio_en,birth_place_ar,death_place_ar,order_num,published,metadata) values ('71e31a81-d6b5-5dab-a15f-b3b66842a26d','اليسع عليه السلام','Elisha','alyasa','كان اليسع من الأنبياء الذين واصلوا طريق الإصلاح بعد إلياس. دعا قومه إلى الطاعة والاستقامة، وذكره الله في الأخيار، وفي قصته قيمة استمرار الرسالة وعدم اليأس من الإصلاح.','A prophet mentioned in the Quran and Islamic tradition.','الشام','الشام',21,true,'{"content_source":"Original editorial summary based on Quran and authenticated Islamic tradition","editor":"Zikr"}') on conflict (slug) do update set name_ar=excluded.name_ar,name_en=excluded.name_en,bio_ar=excluded.bio_ar,bio_en=excluded.bio_en,birth_place_ar=excluded.birth_place_ar,death_place_ar=excluded.death_place_ar,order_num=excluded.order_num,published=true,metadata=excluded.metadata;
