insert into public.prophets (id,name_ar,name_en,slug,bio_ar,bio_en,birth_place_ar,death_place_ar,order_num,published,metadata) values ('5312fc33-a213-48c0-a311-75a5608c9287','محمد ﷺ','Muhammad','muhammad','خاتم الأنبياء محمد ﷺ، بعثه الله رحمة للعالمين بالقرآن والتوحيد. صبر على الأذى، وبنى مجتمع المدينة على الأخوة والعدل، وأدى الأمانة حتى اكتمل الدين وبلغت الرسالة.','A prophet mentioned in the Quran and Islamic tradition.','مكة المكرمة','المدينة المنورة',25,true,'{"content_source":"Original editorial summary based on Quran and authenticated Islamic tradition","editor":"Zikr"}') on conflict (slug) do update set name_ar=excluded.name_ar,name_en=excluded.name_en,bio_ar=excluded.bio_ar,bio_en=excluded.bio_en,birth_place_ar=excluded.birth_place_ar,death_place_ar=excluded.death_place_ar,order_num=excluded.order_num,published=true,metadata=excluded.metadata;
insert into public.prophet_sections (id,prophet_id,title_ar,title_en,content_ar,content_en,section_type,order_num) values ('ce57865d-3178-5e11-b42a-143d5d184bc6','5312fc33-a213-48c0-a311-75a5608c9287','لمحة القصة','Story overview','تبدأ القصة من أصلها كما ورد في القرآن والسنة الصحيحة، مع التركيز على التوحيد والصبر والعمل الصالح. خاتم الأنبياء محمد ﷺ، بعثه الله رحمة للعالمين بالقرآن والتوحيد. صبر على الأذى، وبنى مجتمع المدينة على الأخوة والعدل، وأدى الأمانة حتى اكتمل الدين وبلغت الرسالة.','This section is an original editorial summary for educational use.','biography',1) on conflict (id) do update set prophet_id=excluded.prophet_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,section_type=excluded.section_type,order_num=excluded.order_num;
insert into public.prophet_sections (id,prophet_id,title_ar,title_en,content_ar,content_en,section_type,order_num) values ('0da6ef0d-f5ec-5c8e-97cb-e13d659c9e3d','5312fc33-a213-48c0-a311-75a5608c9287','الدروس والعبر','Lessons and reflections','تعلّمنا سيرة هذا النبي أن الإيمان يظهر في المواقف، وأن الصبر والصدق والرجوع إلى الله طريق النجاة. خاتم الأنبياء محمد ﷺ، بعثه الله رحمة للعالمين بالقرآن والتوحيد. صبر على الأذى، وبنى مجتمع المدينة على الأخوة والعدل، وأدى الأمانة حتى اكتمل الدين وبلغت الرسالة.','This section is an original editorial summary for educational use.','teachings',2) on conflict (id) do update set prophet_id=excluded.prophet_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,section_type=excluded.section_type,order_num=excluded.order_num;
insert into public.prophet_sections (id,prophet_id,title_ar,title_en,content_ar,content_en,section_type,order_num) values ('2af5d360-696f-5e95-96ab-271c1ae25aa0','5312fc33-a213-48c0-a311-75a5608c9287','آيات مرتبطة','Quran connections','تظهر معاني قصة محمد ﷺ في مواضع متعددة من القرآن الكريم، ويستحسن تدبر سياق الآيات وعدم فصل القصة عن مقصدها في إصلاح القلب والعمل. يمكن للقارئ أن يراجع الآيات التي ذكرت هذا النبي، وأن يتدبر كيف يربط القرآن بين القصة والهداية والسلوك.','This section is an original editorial summary for educational use.','legacy',3) on conflict (id) do update set prophet_id=excluded.prophet_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,section_type=excluded.section_type,order_num=excluded.order_num;
insert into public.battles (id,name_ar,name_en,slug,description_ar,description_en,year_hijri,order_num,published) values ('74f643f0-4a96-5959-8dbc-6e0d592a06cc','غزوة بدر الكبرى','The Great Battle of Badr','badr','كانت بدر أول مواجهة فاصلة بين المسلمين وقريش، وفيها ظهر أثر الإيمان والتنظيم والشورى مع قلة العدد والعدة.','A documented campaign from the Prophetic biography, presented with chronology and lessons.',2,2,true) on conflict (slug) do update set name_ar=excluded.name_ar,name_en=excluded.name_en,description_ar=excluded.description_ar,description_en=excluded.description_en,year_hijri=excluded.year_hijri,order_num=excluded.order_num,published=true;
insert into public.battle_events (id,battle_id,title_ar,title_en,content_ar,content_en,event_type,order_num) values ('15128563-91b5-5933-9336-5b734f8832c1',(select id from public.battles where slug='badr' limit 1),'التمهيد والسياق','Context and preparation','يوضح هذا الحدث الظروف السياسية والاجتماعية التي سبقت الغزوة، مع بيان أهمية الشورى والاستعداد وعدم التسرع. ويتصل ذلك بسياق غزوة بدر الكبرى التي وقعت في السنة الهجرية 2. تُعرض المعلومة هنا بصياغة تحريرية تعليمية، مع الدعوة إلى الرجوع إلى كتب السيرة المعتمدة للتوسع.','An original educational chronology note for this campaign.','context',1) on conflict (id) do update set battle_id=excluded.battle_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,event_type=excluded.event_type,order_num=excluded.order_num;
insert into public.battle_events (id,battle_id,title_ar,title_en,content_ar,content_en,event_type,order_num) values ('1193ea43-80e7-5864-bd5a-6994e9457ef5',(select id from public.battles where slug='badr' limit 1),'بداية المواجهة','Opening of the encounter','بدأت المواجهة وفق ترتيب واضح، وكان ثبات القيادة وحسن توزيع الأدوار سببًا في حماية الصف وتقليل الفوضى. ويتصل ذلك بسياق غزوة بدر الكبرى التي وقعت في السنة الهجرية 2. تُعرض المعلومة هنا بصياغة تحريرية تعليمية، مع الدعوة إلى الرجوع إلى كتب السيرة المعتمدة للتوسع.','An original educational chronology note for this campaign.','battle',2) on conflict (id) do update set battle_id=excluded.battle_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,event_type=excluded.event_type,order_num=excluded.order_num;
insert into public.battle_events (id,battle_id,title_ar,title_en,content_ar,content_en,event_type,order_num) values ('cc751e0f-770b-544b-9f4c-3f8362065371',(select id from public.battles where slug='badr' limit 1),'التحول الحاسم','Turning point','تكشف هذه المرحلة أن الأسباب المادية وحدها لا تكفي، وأن الطاعة والصبر والرجوع إلى الله من أهم أسباب الثبات. ويتصل ذلك بسياق غزوة بدر الكبرى التي وقعت في السنة الهجرية 2. تُعرض المعلومة هنا بصياغة تحريرية تعليمية، مع الدعوة إلى الرجوع إلى كتب السيرة المعتمدة للتوسع.','An original educational chronology note for this campaign.','turning-point',3) on conflict (id) do update set battle_id=excluded.battle_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,event_type=excluded.event_type,order_num=excluded.order_num;
insert into public.battle_events (id,battle_id,title_ar,title_en,content_ar,content_en,event_type,order_num) values ('87914faa-e094-5517-9856-b2eb0f13da9d',(select id from public.battles where slug='badr' limit 1),'النتائج والعبر','Results and lessons','انتهت الغزوة بنتائج سياسية وتربوية، ومن أبرز العبر حفظ العهود، ورعاية الضعفاء، وعدم تحويل النصر إلى ظلم أو غرور. ويتصل ذلك بسياق غزوة بدر الكبرى التي وقعت في السنة الهجرية 2. تُعرض المعلومة هنا بصياغة تحريرية تعليمية، مع الدعوة إلى الرجوع إلى كتب السيرة المعتمدة للتوسع.','An original educational chronology note for this campaign.','lessons',4) on conflict (id) do update set battle_id=excluded.battle_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,event_type=excluded.event_type,order_num=excluded.order_num;
insert into public.battles (id,name_ar,name_en,slug,description_ar,description_en,year_hijri,order_num,published) values ('f0849451-6fda-5ab9-b70a-0d5d859abedf','غزوة أحد','Battle of Uhud','uhud','أحد مدرسة في الطاعة والقيادة ومراجعة الأخطاء؛ بدأت بنصر للمسلمين ثم تغيرت الموازين عندما خالف بعض الرماة الأمر، فتعلم المسلمون عواقب التنازع.','A documented campaign from the Prophetic biography, presented with chronology and lessons.',3,3,true) on conflict (slug) do update set name_ar=excluded.name_ar,name_en=excluded.name_en,description_ar=excluded.description_ar,description_en=excluded.description_en,year_hijri=excluded.year_hijri,order_num=excluded.order_num,published=true;
