insert into public.battle_events (id,battle_id,title_ar,title_en,content_ar,content_en,event_type,order_num) values ('d9c5f795-000b-5ffb-a4aa-cd445f024b96',(select id from public.battles where slug='khandaq' limit 1),'النتائج والعبر','Results and lessons','انتهت الغزوة بنتائج سياسية وتربوية، ومن أبرز العبر حفظ العهود، ورعاية الضعفاء، وعدم تحويل النصر إلى ظلم أو غرور. ويتصل ذلك بسياق غزوة الخندق التي وقعت في السنة الهجرية 5. تُعرض المعلومة هنا بصياغة تحريرية تعليمية، مع الدعوة إلى الرجوع إلى كتب السيرة المعتمدة للتوسع.','An original educational chronology note for this campaign.','lessons',4) on conflict (id) do update set battle_id=excluded.battle_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,event_type=excluded.event_type,order_num=excluded.order_num;
insert into public.battles (id,name_ar,name_en,slug,description_ar,description_en,year_hijri,order_num,published) values ('375011f1-78c2-5257-bc36-eff0709f3da5','غزوة خيبر','Battle of Khaybar','khaybar','جاءت خيبر بعد الحديبية، وانتهت بفتح حصونها وفق قيادة نبوية تجمع بين التخطيط والرحمة والوفاء بالعهد.','A documented campaign from the Prophetic biography, presented with chronology and lessons.',7,7,true) on conflict (slug) do update set name_ar=excluded.name_ar,name_en=excluded.name_en,description_ar=excluded.description_ar,description_en=excluded.description_en,year_hijri=excluded.year_hijri,order_num=excluded.order_num,published=true;
insert into public.battle_events (id,battle_id,title_ar,title_en,content_ar,content_en,event_type,order_num) values ('7351db06-379c-5f41-a2fc-807634210e05',(select id from public.battles where slug='khaybar' limit 1),'التمهيد والسياق','Context and preparation','يوضح هذا الحدث الظروف السياسية والاجتماعية التي سبقت الغزوة، مع بيان أهمية الشورى والاستعداد وعدم التسرع. ويتصل ذلك بسياق غزوة خيبر التي وقعت في السنة الهجرية 7. تُعرض المعلومة هنا بصياغة تحريرية تعليمية، مع الدعوة إلى الرجوع إلى كتب السيرة المعتمدة للتوسع.','An original educational chronology note for this campaign.','context',1) on conflict (id) do update set battle_id=excluded.battle_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,event_type=excluded.event_type,order_num=excluded.order_num;
insert into public.battle_events (id,battle_id,title_ar,title_en,content_ar,content_en,event_type,order_num) values ('53e916a0-46df-5b4d-9cab-94ecab056d6a',(select id from public.battles where slug='khaybar' limit 1),'بداية المواجهة','Opening of the encounter','بدأت المواجهة وفق ترتيب واضح، وكان ثبات القيادة وحسن توزيع الأدوار سببًا في حماية الصف وتقليل الفوضى. ويتصل ذلك بسياق غزوة خيبر التي وقعت في السنة الهجرية 7. تُعرض المعلومة هنا بصياغة تحريرية تعليمية، مع الدعوة إلى الرجوع إلى كتب السيرة المعتمدة للتوسع.','An original educational chronology note for this campaign.','battle',2) on conflict (id) do update set battle_id=excluded.battle_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,event_type=excluded.event_type,order_num=excluded.order_num;
insert into public.battle_events (id,battle_id,title_ar,title_en,content_ar,content_en,event_type,order_num) values ('afb43cdd-e5f6-5868-b9b6-27309b35ee99',(select id from public.battles where slug='khaybar' limit 1),'التحول الحاسم','Turning point','تكشف هذه المرحلة أن الأسباب المادية وحدها لا تكفي، وأن الطاعة والصبر والرجوع إلى الله من أهم أسباب الثبات. ويتصل ذلك بسياق غزوة خيبر التي وقعت في السنة الهجرية 7. تُعرض المعلومة هنا بصياغة تحريرية تعليمية، مع الدعوة إلى الرجوع إلى كتب السيرة المعتمدة للتوسع.','An original educational chronology note for this campaign.','turning-point',3) on conflict (id) do update set battle_id=excluded.battle_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,event_type=excluded.event_type,order_num=excluded.order_num;
insert into public.battle_events (id,battle_id,title_ar,title_en,content_ar,content_en,event_type,order_num) values ('afc73414-2a8a-5af3-b596-024555f4b7ad',(select id from public.battles where slug='khaybar' limit 1),'النتائج والعبر','Results and lessons','انتهت الغزوة بنتائج سياسية وتربوية، ومن أبرز العبر حفظ العهود، ورعاية الضعفاء، وعدم تحويل النصر إلى ظلم أو غرور. ويتصل ذلك بسياق غزوة خيبر التي وقعت في السنة الهجرية 7. تُعرض المعلومة هنا بصياغة تحريرية تعليمية، مع الدعوة إلى الرجوع إلى كتب السيرة المعتمدة للتوسع.','An original educational chronology note for this campaign.','lessons',4) on conflict (id) do update set battle_id=excluded.battle_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,event_type=excluded.event_type,order_num=excluded.order_num;
insert into public.battles (id,name_ar,name_en,slug,description_ar,description_en,year_hijri,order_num,published) values ('ead856bc-af4f-5f9d-be2f-acab1fbb0947','غزوة حنين','Battle of Hunayn','hunayn','في حنين أعجب بعض المسلمين بكثرتهم، فذكّرهم الله أن النصر من عنده وحده، ثم ثبت النبي ﷺ ومن معه حتى عاد الجيش إلى التوازن.','A documented campaign from the Prophetic biography, presented with chronology and lessons.',8,8,true) on conflict (slug) do update set name_ar=excluded.name_ar,name_en=excluded.name_en,description_ar=excluded.description_ar,description_en=excluded.description_en,year_hijri=excluded.year_hijri,order_num=excluded.order_num,published=true;
