insert into public.battle_events (id,battle_id,title_ar,title_en,content_ar,content_en,event_type,order_num) values ('a019ed55-2e8f-54bd-b7c8-b768e217930e',(select id from public.battles where slug='hunayn' limit 1),'النتائج والعبر','Results and lessons','انتهت الغزوة بنتائج سياسية وتربوية، ومن أبرز العبر حفظ العهود، ورعاية الضعفاء، وعدم تحويل النصر إلى ظلم أو غرور. ويتصل ذلك بسياق غزوة حنين التي وقعت في السنة الهجرية 8. تُعرض المعلومة هنا بصياغة تحريرية تعليمية، مع الدعوة إلى الرجوع إلى كتب السيرة المعتمدة للتوسع.','An original educational chronology note for this campaign.','lessons',4) on conflict (id) do update set battle_id=excluded.battle_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,event_type=excluded.event_type,order_num=excluded.order_num;
insert into public.kids_content (id,title_ar,title_en,slug,type,content_ar,content_en,age_group,quiz_data,published,is_active,metadata) values ('24edbcd2-91d1-5f19-9f59-c8097c1a54c3','قصة أصحاب الفيل','The People of the Elephant','story-ashab-al-fil','story','كان أبرهة يريد هدم الكعبة، فسار بجيش كبير ومعه فيل. حفظ الله بيته وأرسل طيرًا ترميهم بحجارة من سجيل، فعرف الأطفال أن حماية الله أقوى من كل قوة. الدرس: نحترم بيوت الله ونثق بحفظه. ','Original educational content prepared for Zikr families.','6-8',NULL,true,true,'{"reward":"وسام حامي الكعبة","objective":"تعلم معنى الحماية والثقة بالله"}') on conflict (slug) do update set title_ar=excluded.title_ar,title_en=excluded.title_en,type=excluded.type,content_ar=excluded.content_ar,content_en=excluded.content_en,age_group=excluded.age_group,quiz_data=excluded.quiz_data,published=true,is_active=true,metadata=excluded.metadata;
insert into public.kids_content (id,title_ar,title_en,slug,type,content_ar,content_en,age_group,quiz_data,published,is_active,metadata) values ('1f939452-7ac0-523d-be1f-1d5ae4d6b0f1','يونس والحوت','Yunus and the Whale','story-yunus-kids','story','خرج يونس من قومه ثم وجد نفسه في بطن الحوت، فنادى الله بصدق فاستجاب له. الدرس: لا نيأس من رحمة الله ونعتذر عندما نخطئ.','Original educational content prepared for Zikr families.','6-8',NULL,true,true,'{"reward":"نجمة التوبة","objective":"تعلم الاعتذار والرجوع إلى الله"}') on conflict (slug) do update set title_ar=excluded.title_ar,title_en=excluded.title_en,type=excluded.type,content_ar=excluded.content_ar,content_en=excluded.content_en,age_group=excluded.age_group,quiz_data=excluded.quiz_data,published=true,is_active=true,metadata=excluded.metadata;
insert into public.kids_content (id,title_ar,title_en,slug,type,content_ar,content_en,age_group,quiz_data,published,is_active,metadata) values ('74f4f82b-017c-56a3-a065-e6a4e74cf8d7','سليمان والنملة','Sulaiman and the Ant','story-sulayman-ant','story','سمع سليمان نملة تحذر قومها، فتبسم وشكر الله. الدرس: نرحم المخلوقات الصغيرة ولا نسخر من أحد.','Original educational content prepared for Zikr families.','3-5',NULL,true,true,'{"reward":"قلب رحيم","objective":"تنمية الرحمة والانتباه"}') on conflict (slug) do update set title_ar=excluded.title_ar,title_en=excluded.title_en,type=excluded.type,content_ar=excluded.content_ar,content_en=excluded.content_en,age_group=excluded.age_group,quiz_data=excluded.quiz_data,published=true,is_active=true,metadata=excluded.metadata;
insert into public.kids_content (id,title_ar,title_en,slug,type,content_ar,content_en,age_group,quiz_data,published,is_active,metadata) values ('855f481c-6531-5876-bc2c-59903ada9960','رتّب خطوات الوضوء','Arrange the Wudu Steps','game-wudu-steps','game','رتّب خطوات الوضوء من النية إلى غسل الرجلين، ثم راجع الإجابة وتعلم أن النظافة عبادة.','Original educational content prepared for Zikr families.','6-8','{"questions":[{"text":"ما أول ما نستحضره عند الوضوء؟","options":["النية","النوم","اللعب","الطعام"],"correctAnswer":0},{"text":"أي عضو نغسله بعد الوجه؟","options":["الرجلان","اليدان إلى المرفقين","الرأس","الأذنان"],"correctAnswer":1},{"text":"كم مرة يُستحب غسل العضو؟","options":["ثلاثًا دون إسراف","سبعًا دائمًا","مرة في الشهر","لا يُغسل"],"correctAnswer":0}]}',true,true,'{"gameType":"quiz","reward":"وسام الطهارة","objective":"تعلم ترتيب الوضوء"}') on conflict (slug) do update set title_ar=excluded.title_ar,title_en=excluded.title_en,type=excluded.type,content_ar=excluded.content_ar,content_en=excluded.content_en,age_group=excluded.age_group,quiz_data=excluded.quiz_data,published=true,is_active=true,metadata=excluded.metadata;
insert into public.kids_content (id,title_ar,title_en,slug,type,content_ar,content_en,age_group,quiz_data,published,is_active,metadata) values ('5bb2f665-4c31-5550-9d1c-ffd1e5083633','لعبة أوقات الصلاة','Prayer Times Game','game-salah-times','game','صِل كل صلاة بوقتها التقريبي، وتذكر أن الصلاة صلة يومية بين العبد وربه.','Original educational content prepared for Zikr families.','9-12','{"questions":[{"text":"متى يدخل وقت الفجر؟","options":["من طلوع الفجر الصادق","بعد الظهر","عند منتصف الليل فقط","بعد المغرب"],"correctAnswer":0},{"text":"أي صلاة وقتها بعد زوال الشمس؟","options":["الظهر","الفجر","العشاء","المغرب"],"correctAnswer":0},{"text":"ما الصلاة التي يدخل وقتها بغروب الشمس؟","options":["المغرب","العصر","الضحى","الفجر"],"correctAnswer":0}]}',true,true,'{"gameType":"matching","reward":"مفتاح الصلاة","objective":"ربط الصلوات بأوقاتها"}') on conflict (slug) do update set title_ar=excluded.title_ar,title_en=excluded.title_en,type=excluded.type,content_ar=excluded.content_ar,content_en=excluded.content_en,age_group=excluded.age_group,quiz_data=excluded.quiz_data,published=true,is_active=true,metadata=excluded.metadata;
insert into public.kids_content (id,title_ar,title_en,slug,type,content_ar,content_en,age_group,quiz_data,published,is_active,metadata) values ('73536ba2-faa5-53ee-ad29-8a0223395a0a','اختبر معلوماتك عن الأنبياء','Prophets Quiz','quiz-prophets','quiz','اختبار قصير يراجع أسماء الأنبياء ومعاني الصبر والتوحيد من خلال أسئلة مناسبة للناشئة.','Original educational content prepared for Zikr families.','9-12','{"questions":[{"text":"من أول الأنبياء؟","options":["آدم عليه السلام","نوح عليه السلام","موسى عليه السلام","يوسف عليه السلام"],"correctAnswer":0},{"text":"من بنى الكعبة مع إبراهيم؟","options":["إسماعيل","هارون","يحيى","داود"],"correctAnswer":0},{"text":"من النبي الذي ابتلعه الحوت؟","options":["يونس","صالح","شعيب","إدريس"],"correctAnswer":0}]}',true,true,'{"gameType":"quiz","reward":"باحث القصص","objective":"مراجعة المعلومات الإسلامية"}') on conflict (slug) do update set title_ar=excluded.title_ar,title_en=excluded.title_en,type=excluded.type,content_ar=excluded.content_ar,content_en=excluded.content_en,age_group=excluded.age_group,quiz_data=excluded.quiz_data,published=true,is_active=true,metadata=excluded.metadata;
insert into public.kids_content (id,title_ar,title_en,slug,type,content_ar,content_en,age_group,quiz_data,published,is_active,metadata) values ('c3cea784-13ff-52ce-8338-9d718635dcc6','أكمل جملة الخُلُق الجميل','Good Manners Puzzle','puzzle-good-manners','game','اسحب الكلمة المناسبة لإكمال الجمل: المسلم صادق، رحيم، أمين، ويقول خيرًا أو يصمت.','Original educational content prepared for Zikr families.','6-8','{"questions":[{"text":"المسلم ____ ولا يكذب.","options":["صادق","غاضب","مؤذٍ","متكبر"],"correctAnswer":0},{"text":"نرحم ____ ونساعد المحتاج.","options":["الضعيف","الظلم","الكذب","الأذى"],"correctAnswer":0}]}',true,true,'{"gameType":"word-puzzle","reward":"تاج الخُلُق","objective":"تثبيت الأخلاق الإسلامية"}') on conflict (slug) do update set title_ar=excluded.title_ar,title_en=excluded.title_en,type=excluded.type,content_ar=excluded.content_ar,content_en=excluded.content_en,age_group=excluded.age_group,quiz_data=excluded.quiz_data,published=true,is_active=true,metadata=excluded.metadata;
insert into public.kids_content (id,title_ar,title_en,slug,type,content_ar,content_en,age_group,quiz_data,published,is_active,metadata) values ('6b38b233-eddc-5a99-bb1f-593395fe2275','خطة حفظ سورة الفلق','Memorize Al-Falaq','memorize-al-falaq','game','خطة سبعة أيام لحفظ سورة الفلق مع تكرار الآيات، الاستماع، والمراجعة اليومية. اجعل الحفظ قصيرًا ثابتًا ومفرحًا.','Original educational content prepared for Zikr families.','6-8',NULL,true,true,'{"memorizationTarget":"سورة الفلق","durationDays":7,"dailyPlan":["استمع للسورة مرتين","احفظ الآيتين الأولى والثانية","أكمل آيتين جديدتين","اربط الآيات","اقرأ مع أحد الوالدين","سمّع السورة كاملة","مراجعة وفرحة الإنجاز"],"reward":"وسام الحافظ الصغير","objective":"بناء عادة حفظ يومية"}') on conflict (slug) do update set title_ar=excluded.title_ar,title_en=excluded.title_en,type=excluded.type,content_ar=excluded.content_ar,content_en=excluded.content_en,age_group=excluded.age_group,quiz_data=excluded.quiz_data,published=true,is_active=true,metadata=excluded.metadata;
insert into public.kids_content (id,title_ar,title_en,slug,type,content_ar,content_en,age_group,quiz_data,published,is_active,metadata) values ('3efae434-e46f-5c88-a964-2533dda26c4f','تقويم أعمال الخير','Kindness Calendar','activity-kindness-calendar','game','كل يوم اختَر عملًا صغيرًا: ابتسامة، مساعدة الوالدين، إطعام طائر، أو كلمة طيبة. ضع علامة عند الإنجاز وشارك فرحتك مع الأسرة.','Original educational content prepared for Zikr families.','3-5',NULL,true,true,'{"gameType":"daily-challenge","durationDays":14,"reward":"حديقة الخير","objective":"تحويل الأخلاق إلى عادة"}') on conflict (slug) do update set title_ar=excluded.title_ar,title_en=excluded.title_en,type=excluded.type,content_ar=excluded.content_ar,content_en=excluded.content_en,age_group=excluded.age_group,quiz_data=excluded.quiz_data,published=true,is_active=true,metadata=excluded.metadata;
insert into public.kids_content (id,title_ar,title_en,slug,type,content_ar,content_en,age_group,quiz_data,published,is_active,metadata) values ('92e02979-84cd-5669-a915-af2bd77ae01c','مريم عليها السلام','Maryam Story','story-maryam-kids','story','كانت مريم عليها السلام عابدة طاهرة اصطفاها الله، وواجهت ابتلاءً عظيمًا بثقة وصبر. تذكر القصة أن كرامة الإنسان في طاعته، وأن الله يرزق من يشاء بغير حساب.','Original educational content prepared for Zikr families.','9-12',NULL,true,true,'{"reward":"زهرة العفة","objective":"تعلم الصبر والعفة"}') on conflict (slug) do update set title_ar=excluded.title_ar,title_en=excluded.title_en,type=excluded.type,content_ar=excluded.content_ar,content_en=excluded.content_en,age_group=excluded.age_group,quiz_data=excluded.quiz_data,published=true,is_active=true,metadata=excluded.metadata;
